local CoreOvenMaker = {}
local PRODUCTS = {
    iron_coreoven = { name = "Železni peč za jedrca", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni peč za jedrca za livarje." },
    bronze_coreoven = { name = "Bronast peč za jedrca", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast peč za jedrca za livarje." },
    silver_coreoven = { name = "Srebrn peč za jedrca", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn peč za jedrca za livarje." },
    gilded_coreoven = { name = "Pozlačen peč za jedrca", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen peč za jedrca za livarje." },
    jewel_set_coreoven = { name = "Draguljast peč za jedrca", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast peč za jedrca za livarje." },
    royal_sovereign_coreoven = { name = "Kraljevski suveren peč za jedrca", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren peč za jedrca z biseri za krono." },
}
local BUILDINGS = {
    coreoven_workshop = { name = "Coreoven delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    coreoven_house = { name = "Coreoven hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_coreoven_atelier = { name = "Mojstrski coreoven atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_coreoven_palace = { name = "Suverena coreoven palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CoreOvenMaker.ironStock=18; CoreOvenMaker.bronzeStock=14; CoreOvenMaker.woodStock=10; CoreOvenMaker.leatherStock=8; CoreOvenMaker.silverStock=8; CoreOvenMaker.goldStock=6; CoreOvenMaker.jewelStock=4; CoreOvenMaker.pearlStock=4
CoreOvenMaker.productStock = {}; CoreOvenMaker.buildings = {}; CoreOvenMaker.maker = nil; CoreOvenMaker.activeMaking = {}; CoreOvenMaker.totalProducts = 0; CoreOvenMaker.dayTimer = 0
function CoreOvenMaker.init() CoreOvenMaker.ironStock=18; CoreOvenMaker.bronzeStock=14; CoreOvenMaker.woodStock=10; CoreOvenMaker.leatherStock=8; CoreOvenMaker.silverStock=8; CoreOvenMaker.goldStock=6; CoreOvenMaker.jewelStock=4; CoreOvenMaker.pearlStock=4; CoreOvenMaker.productStock={}; CoreOvenMaker.buildings={}; CoreOvenMaker.maker=nil; CoreOvenMaker.activeMaking={}; CoreOvenMaker.totalProducts=0; CoreOvenMaker.dayTimer=0; print("[CoreOvenMaker] Royal Core Oven Maker System initialized (6 products, 4 buildings)") end
function CoreOvenMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoreOvenMaker.maker={name=n or ("Pečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečar najet: %s (spretnost: %d)",CoreOvenMaker.maker.name,s),"success") end; return true end
function CoreOvenMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoreOvenMaker.build(id) local ok,e=CoreOvenMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoreOvenMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoreOvenMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoreOvenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoreOvenMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoreOvenMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoreOvenMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoreOvenMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoreOvenMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoreOvenMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoreOvenMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoreOvenMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoreOvenMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoreOvenMaker.buildings==0 then return false,"Potrebna pečna delavnica" end; if not CoreOvenMaker.maker then return false,"Potreben pečar" end; return true end
function CoreOvenMaker.make(pt,qty) qty=qty or 1; local ok,e=CoreOvenMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoreOvenMaker.ironStock=CoreOvenMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoreOvenMaker.bronzeStock=CoreOvenMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoreOvenMaker.woodStock=CoreOvenMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoreOvenMaker.leatherStock=CoreOvenMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoreOvenMaker.silverStock=CoreOvenMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoreOvenMaker.goldStock=CoreOvenMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoreOvenMaker.jewelStock=CoreOvenMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoreOvenMaker.pearlStock=CoreOvenMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoreOvenMaker.maker then t=math.max(1,t-math.floor(CoreOvenMaker.maker.skill/13)) end; table.insert(CoreOvenMaker.activeMaking,{id="coreoven_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoreOvenMaker.completeMaking(m) local q=1.0+(CoreOvenMaker.getQualityBonus()/100); if CoreOvenMaker.maker then q=q+(CoreOvenMaker.maker.skill/140) end; q=math.min(2.5,q); CoreOvenMaker.productStock[m.productType]=(CoreOvenMaker.productStock[m.productType] or 0)+m.quantity; CoreOvenMaker.totalProducts=CoreOvenMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoreOvenMaker.maker then CoreOvenMaker.maker.itemsMade=CoreOvenMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoreOvenMaker.maker.skill=math.min(100,CoreOvenMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Peč izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coreoven.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoreOvenMaker.update(dt) if not _G.state then return end; CoreOvenMaker.dayTimer=CoreOvenMaker.dayTimer+dt; if CoreOvenMaker.dayTimer>=30 then CoreOvenMaker.dayTimer=0; for i=#CoreOvenMaker.activeMaking,1,-1 do local m=CoreOvenMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoreOvenMaker.completeMaking(m); table.remove(CoreOvenMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoreOvenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoreOvenMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoreOvenMaker.getStats() return {ironStock=CoreOvenMaker.ironStock,bronzeStock=CoreOvenMaker.bronzeStock,woodStock=CoreOvenMaker.woodStock,leatherStock=CoreOvenMaker.leatherStock,silverStock=CoreOvenMaker.silverStock,goldStock=CoreOvenMaker.goldStock,jewelStock=CoreOvenMaker.jewelStock,pearlStock=CoreOvenMaker.pearlStock,productStock=CoreOvenMaker.productStock,numBuildings=#CoreOvenMaker.buildings,hasMaker=CoreOvenMaker.maker~=nil,makerName=CoreOvenMaker.maker and CoreOvenMaker.maker.name or "—",makerSkill=CoreOvenMaker.maker and CoreOvenMaker.maker.skill or 0,activeMaking=#CoreOvenMaker.activeMaking,totalProducts=CoreOvenMaker.totalProducts} end
return CoreOvenMaker
